+    /**
+     * Resolves an archive entry name against the extraction directory and makes sure the resulting
+     * file stays inside that directory. This prevents malicious archives from writing files to
+     * arbitrary locations on the filesystem (a.k.a. "Zip Slip", CWE-22).
+     *
+     * @param dest the directory the archive is extracted into
+     * @param name the entry name as declared in the archive
+     * @return the sanitized destination file
+     * @throws IOException if the entry would be extracted outside of {@code dest}
+     */
+    private static File validateArchiveEntry(File dest, String name) throws IOException {
+        if (name == null || name.isEmpty()) {
+            throw new IOException("Invalid archive entry: empty name.");
+        }
+
+        File destDir = dest.getCanonicalFile();
+        File file = new File(destDir, name).getCanonicalFile();
+
+        if (!file.toPath().startsWith(destDir.toPath())) {
+            throw new IOException(
+                    "Invalid archive entry, it tries to write outside of the destination directory: "
+                            + name);
+        }
+
+        return file;
+    }
