+// Application ids end up as a path segment below the applicationData
+// directory, so they must never be able to contain a path separator or a
+// relative path segment. Note that on Windows both '/' and '\' are treated
+// as directory separators by path.join(), so a denylist of '/' only is not
+// sufficient. Use a strict allowlist instead.
+const VALID_APPID = /^[A-Za-z0-9._@-]+$/
+
+function validateAppId(appid: string) {
+  if (
+    typeof appid !== 'string' ||
+    appid.length === 0 ||
+    appid.length >= 30 ||
+    !VALID_APPID.test(appid) ||
+    appid === '.' ||
+    appid === '..' ||
+    appid.indexOf('..') !== -1
+  ) {
+    return false
+  }
+  return true
+}
+
+// Defence in depth: make sure the resulting path can not escape the
+// applicationData directory, whatever the platform's path semantics are.
+function isWithinDirectory(basePath: string, targetPath: string) {
+  const base = path.resolve(basePath)
+  const target = path.resolve(targetPath)
+  return target === base || target.startsWith(base + path.sep)
+}
+
+function safeApplicationDataPath(basePath: string, ...segments: string[]) {
+  const result = path.join(basePath, ...segments)
+  if (!isWithinDirectory(basePath, result)) {
+    throw new Error('Invalid application data path')
+  }
+  return result
+}

