+/**
+ * Configuration used to sanitize SVG markup. We only ever want to render SVG
+ * (plus the MathML/HTML that may legitimately live inside a <foreignObject>),
+ * and we never want scripts, event handlers or javascript:/data: URLs to
+ * survive, since the markup comes from untrusted project (.sb3) files.
+ * @type {object}
+ */
+const SANITIZE_CONFIG = {
+    USE_PROFILES: {svg: true, svgFilters: true},
+    // Explicitly drop anything that can execute script.
+    FORBID_TAGS: ['script', 'foreignObject', 'use', 'set', 'animate'],
+    FORBID_ATTR: ['xlink:href', 'href'],
+    ADD_ATTR: ['xmlns', 'xmlns:xlink', 'version'],
+    KEEP_CONTENT: false
+};
+
+const sanitizeSvg = {};
+
+/**
+ * Sanitize an SVG string, stripping any content that could execute script.
+ * @param {string} rawSvgText The unsanitized SVG markup.
+ * @returns {string} The sanitized SVG markup.
+ */
+sanitizeSvg.sanitizeSvgText = function (rawSvgText) {
+    // Nothing to do for non-strings; let the caller fail on its own terms.
+    if (typeof rawSvgText !== 'string') return rawSvgText;
+    return DOMPurify.sanitize(rawSvgText, SANITIZE_CONFIG);
+};
+
+/**
+ * Sanitize a byte stream (e.g. the contents of an SVG asset inside an .sb3).
+ * @param {Uint8Array} data The unsanitized UTF-8 encoded SVG data.
+ * @returns {Uint8Array} The sanitized UTF-8 encoded SVG data.
+ */
+sanitizeSvg.sanitizeByteStream = function (data) {
+    const decoder = new TextDecoder();
+    const encoder = new TextEncoder();
+    return encoder.encode(sanitizeSvg.sanitizeSvgText(decoder.decode(data)));
+};
+
+module.exports = sanitizeSvg;
