+/// Intel's QE Identity (a.k.a. Enclave Identity) collateral.
+///
+/// It describes which quoting enclaves are trusted to sign quotes.
+#[derive(Deserialize)]
+#[serde(rename_all = "camelCase")]
+struct QeIdentity {
+    id: String,
+    #[allow(dead_code)]
+    version: u16,
+    issue_date: String,
+    next_update: String,
+    #[allow(dead_code)]
+    tcb_evaluation_data_number: u64,
+    miscselect: String,
+    miscselect_mask: String,
+    attributes: String,
+    attributes_mask: String,
+    mrsigner: String,
+    isvprodid: u16,
+    tcb_levels: Vec<QeTcbLevel>,
+}
+
+#[derive(Deserialize)]
+#[serde(rename_all = "camelCase")]
+struct QeTcbLevel {
+    tcb: QeTcb,
+    tcb_status: String,
+}
+
+#[derive(Deserialize)]
+struct QeTcb {
+    isvsvn: u16,
+}
