+fn decode_hex_bytes(value: &str, expected_len: usize) -> Result<Vec<u8>> {
+    let bytes = hex::decode(value).map_err(|_| anyhow!("Invalid hex string in QE identity"))?;
+    if bytes.len() != expected_len {
+        bail!("Invalid length of hex string in QE identity");
+    }
+    Ok(bytes)
+}
+
+impl QeIdentity {
+    /// Parse and verify the QE identity collateral.
+    ///
+    /// The signature over the raw `enclaveIdentity` body is verified against the leaf
+    /// certificate of `qe_identity_issuer_chain`, and the chain itself is verified up to
+    /// the Intel SGX Root CA. The validity period of the collateral is checked as well.
+    fn from_collateral(quote_collateral: &QuoteCollateralV3, now: u64) -> Result<Self> {
+        let raw_certs =
+            extract_raw_certs(quote_collateral.qe_identity_issuer_chain.as_bytes())
+                .map_err(|_| anyhow!("Failed to parse QE identity issuer chain"))?;
+        if raw_certs.len() < 2 {
+            bail!("QE identity issuer chain is too short");
+        }
+        let signer_cert = webpki::EndEntityCert::try_from(&raw_certs[0][..])
+            .map_err(|_| anyhow!("Failed to parse QE identity signing certificate"))?;
+        let intermediate_certs: Vec<&[u8]> =
+            raw_certs[1..].iter().map(|cert| cert.as_slice()).collect();
+        verify_certificate_chain(&signer_cert, &intermediate_certs, now)
+            .map_err(|_| anyhow!("Failed to verify QE identity issuer chain"))?;
+
+        let asn1_signature = encode_as_der(&quote_collateral.qe_identity_signature)?;
+        if signer_cert
+            .verify_signature(
+                webpki::ECDSA_P256_SHA256,
+                quote_collateral.qe_identity.as_bytes(),
+                &asn1_signature,
+            )
+            .is_err()
+        {
+            bail!("Invalid QE identity signature");
+        }
+
+        let identity: QeIdentity = serde_json::from_str(&quote_collateral.qe_identity)
+            .map_err(|_| anyhow!("Failed to parse QE identity"))?;
+
+        // Only the SGX and TDX quoting enclave identities are supported.
+        if identity.id != "QE" && identity.id != "TD_QE" {
+            bail!("Unsupported QE identity id");
+        }
+
+        let issue_date = chrono::DateTime::parse_from_rfc3339(&identity.issue_date)
+            .map_err(|_| anyhow!("Failed to parse QE identity issueDate"))?;
+        let next_update = chrono::DateTime::parse_from_rfc3339(&identity.next_update)
+            .map_err(|_| anyhow!("Failed to parse QE identity nextUpdate"))?;
+        let now = now as i64;
+        if now < issue_date.timestamp() {
+            bail!("QE identity is not valid yet");
+        }
+        if now >= next_update.timestamp() {
+            bail!("QE identity has expired");
+        }
+
+        Ok(identity)
+    }
+
+    /// Enforce the QE identity policy on the QE report embedded in the quote.
+    fn verify_qe_report(&self, qe_report: &EnclaveReport) -> Result<()> {
+        let miscselect = decode_hex_bytes(&self.miscselect, 4)?;
+        let miscselect_mask = decode_hex_bytes(&self.miscselect_mask, 4)?;
+        for i in 0..miscselect.len() {
+            if qe_report.misc_select[i] & miscselect_mask[i] != miscselect[i] & miscselect_mask[i] {
+                bail!("QE report miscselect mismatch");
+            }
+        }
+
+        let attributes = decode_hex_bytes(&self.attributes, 16)?;
+        let attributes_mask = decode_hex_bytes(&self.attributes_mask, 16)?;
+        for i in 0..attributes.len() {
+            if qe_report.attributes[i] & attributes_mask[i] != attributes[i] & attributes_mask[i] {
+                bail!("QE report attributes mismatch");
+            }
+        }
+
+        let mrsigner = decode_hex_bytes(&self.mrsigner, 32)?;
+        if qe_report.mr_signer[..] != mrsigner[..] {
+            bail!("QE report mrsigner mismatch");
+        }
+
+        if qe_report.isv_prod_id != self.isvprodid {
+            bail!("QE report isvprodid mismatch");
+        }
+
+        // The TCB levels are sorted in descending order of isvsvn, so the first level with an
+        // isvsvn not greater than the one of the QE report is the matching one.
+        let tcb_status = self
+            .tcb_levels
+            .iter()
+            .find(|level| qe_report.isv_svn >= level.tcb.isvsvn)
+            .map(|level| level.tcb_status.as_str())
+            .ok_or_else(|| anyhow!("QE report isvsvn is lower than any known QE TCB level"))?;
+        if tcb_status != "UpToDate" {
+            bail!("QE identity TCB status is not up to date");
+        }
+
+        Ok(())
+    }
+}

