+    * following commands must be redacted, since they may contain
+    * authentication credentials. */
+   if (!bson_strcasecmp (command_name, "authenticate") ||
+       !bson_strcasecmp (command_name, "saslstart") ||
+       !bson_strcasecmp (command_name, "saslcontinue") ||
+       !bson_strcasecmp (command_name, "getnonce") ||
+       !bson_strcasecmp (command_name, "createuser") ||
+       !bson_strcasecmp (command_name, "updateuser") ||
+       !bson_strcasecmp (command_name, "copydbgetnonce") ||
+       !bson_strcasecmp (command_name, "copydbsaslstart") ||
+       !bson_strcasecmp (command_name, "copydb")) {
+      return true;
+   }
+
+   /* hello and legacy hello are only sensitive when speculative
+    * authentication is used. */
+   if (!bson_strcasecmp (command_name, "hello") ||
+       !bson_strcasecmp (command_name, "ismaster")) {
