+package org.apache.streampipes.manager.endpoint;
+
+import org.apache.streampipes.svcdiscovery.SpServiceDiscovery;
+
+import java.net.MalformedURLException;
+import java.net.URL;
+import java.util.List;
+
+/**
+ * Validates that a given URL, which is used to fetch and install pipeline elements from, is provided
+ * by one of the currently registered extensions services.
+ *
+ * <p>Without this check, users would be able to make the core send arbitrary HTTP GET requests to
+ * any address reachable by the core (server-side request forgery).
+ */
+public class ExtensionsServiceEndpointUrlValidator {
+
+  /**
+   * Checks whether the provided URL points to a registered extensions service.
+   *
+   * @param endpointUrl the URL which should be validated
+   * @return true if the URL is served by a registered extensions service, false otherwise
+   */
+  public boolean isValidEndpointUrl(String endpointUrl) {
+    if (endpointUrl == null || endpointUrl.isBlank()) {
+      return false;
+    }
+    try {
+      var providedUrl = new URL(endpointUrl);
+      return getRegisteredServiceUrls()
+          .stream()
+          .anyMatch(serviceUrl -> isSameOrigin(providedUrl, serviceUrl));
+    } catch (MalformedURLException e) {
+      return false;
+    }
+  }
+
+  private boolean isSameOrigin(URL providedUrl,
+                               String serviceUrl) {
+    try {
+      var registeredUrl = new URL(normalize(serviceUrl));
+      return registeredUrl.getProtocol().equalsIgnoreCase(providedUrl.getProtocol())
+          && registeredUrl.getHost().equalsIgnoreCase(providedUrl.getHost())
+          && port(registeredUrl) == port(providedUrl);
+    } catch (MalformedURLException e) {
+      return false;
+    }
+  }
+
+  /**
+   * Registered endpoints are not required to contain a scheme - in this case, http is assumed.
+   */
+  private String normalize(String serviceUrl) {
+    if (serviceUrl.startsWith("http://") || serviceUrl.startsWith("https://")) {
+      return serviceUrl;
+    } else {
+      return "http://" + serviceUrl;
+    }
+  }
+
+  private int port(URL url) {
+    return url.getPort() == -1 ? url.getDefaultPort() : url.getPort();
+  }
+
+  private List<String> getRegisteredServiceUrls() {
+    return SpServiceDiscovery
+        .getServiceDiscovery()
+        .getActivePipelineElementEndpoints();
+  }
+}
